import{c as t,W as a,j as r,n as i}from"./chunks/framework.Bl84hko2.js";const u=JSON.parse('{"title":"Choosing a Preview","description":"","frontmatter":{"id":"guide.choosing-a-preview","title":"Choosing a Preview","describes":["proposal.0001"]},"headers":[],"relativePath":"guides/choosing-a-preview.md","filePath":"guides/choosing-a-preview.md"}'),o={name:"guides/choosing-a-preview.md"};function s(n,e,d,h,p,l){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="choosing-a-preview" tabindex="-1">Choosing a Preview <a class="header-anchor" href="#choosing-a-preview" aria-label="Permalink to “Choosing a Preview”">​</a></h1><h2 id="what-do-i-wire-up-so-i-can-exercise-a-change" tabindex="-1">What do I wire up so I can exercise a change? <a class="header-anchor" href="#what-do-i-wire-up-so-i-can-exercise-a-change" aria-label="Permalink to “What do I wire up so I can exercise a change?”">​</a></h2><p>Wire the cheapest realistic artifact through which you can exercise the changed behavior. This is the preview stage of <a href="./running-a-feature">running a feature</a>.</p><p>Both words carry weight:</p><ul><li><strong>Cheapest</strong> rules out production-grade infrastructure merely to review a pull request.</li><li><strong>Realistic</strong> rules out screenshots, transcripts, and descriptions of what would happen.</li></ul><p>Reviewing prose is not reviewing behavior. The preview exists so you can use the change before deciding whether to accept it.</p><h2 id="match-the-repository-shape" tabindex="-1">Match the repository shape <a class="header-anchor" href="#match-the-repository-shape" aria-label="Permalink to “Match the repository shape”">​</a></h2><p>Choose the surface the proposal changes. The agent wires the matching preview; you exercise it from the pull request before review.</p><table tabindex="0"><thead><tr><th>Repository kind</th><th>Preview</th><th>What you exercise</th></tr></thead><tbody><tr><td>Library</td><td>Prerelease package</td><td>Install it in a dependent project.</td></tr><tr><td>Web app</td><td>Preview deployment</td><td>Click through the changed flow.</td></tr><tr><td>API</td><td>Preview endpoint</td><td>Make real requests.</td></tr><tr><td>Documentation</td><td>Deployed documentation site</td><td>Read the changed documentation.</td></tr><tr><td>CLI</td><td>Installable executable</td><td>Install it and run the changed command.</td></tr><tr><td>Desktop or mobile app</td><td>Installable build</td><td>Install it on a real device and use the changed behavior.</td></tr></tbody></table><p>A mixed repository previews the surface the proposal changed, not every repository shape by habit. A proposal that changes an API does not need a documentation preview as well.</p><p>A pure refactor with no exercisable surface has no preview. Say that in the readiness report rather than fabricating one.</p><h2 id="a-build-artifact-is-not-a-preview" tabindex="-1">A build artifact is not a preview <a class="header-anchor" href="#a-build-artifact-is-not-a-preview" aria-label="Permalink to “A build artifact is not a preview”">​</a></h2><p><strong>A downloadable build artifact is not a preview.</strong> Downloading a zip, unzipping it, and starting a local server is not an act a reviewer will routinely take. The change then gets reviewed as prose instead of behavior.</p><p>This repository made exactly that mistake. Workbench first shipped a downloadable documentation artifact; it now deploys the documentation site to a URL for each pull request.</p><p>A CLI is the exception. Installing its binary is the real act of exercising the program, so an installable executable is a preview for a CLI.</p><h2 id="wire-one-recipe" tabindex="-1">Wire one recipe <a class="header-anchor" href="#wire-one-recipe" aria-label="Permalink to “Wire one recipe”">​</a></h2><p><code>.github/workflows/preview.yml</code> ships a working documentation deployment because Workbench is documentation and process. It also contains commented recipes for the other repository shapes.</p><ol><li>Choose the row that matches your project and the changed surface.</li><li>Wire that recipe in the workflow.</li><li>Delete the recipes that do not apply.</li><li>Open the preview URL from the pull request and exercise the change.</li></ol><p>For the shipped documentation recipe, enable GitHub Pages with <code>gh-pages</code> as its source. The workflow builds every open pull request, deploys beneath <code>pr-preview/pr-&lt;number&gt;/</code>, comments the preview URL on the pull request, and removes the deployment and comment when the pull request closes.</p><p>Do not keep a menu of inactive preview mechanisms as configuration. The comments are examples for adoption; your workflow should express one maintained choice.</p><h2 id="keep-previews-private-by-default" tabindex="-1">Keep previews private by default <a class="header-anchor" href="#keep-previews-private-by-default" aria-label="Permalink to “Keep previews private by default”">​</a></h2><p>A preview is private unless you deliberately decide otherwise. A public preview can expose unfinished behavior, test data, or guides that the repository does not expose.</p><p>GitHub Pages cannot serve privately outside GitHub Enterprise. If your guides must stay private, do not use this repository&#39;s GitHub Pages default. Use the Cloudflare Pages recipe in the workflow instead and gate it behind Cloudflare Access. It requires these repository secrets:</p><table tabindex="0"><thead><tr><th>Secret</th><th>Used for</th></tr></thead><tbody><tr><td><code>CLOUDFLARE_API_TOKEN</code></td><td>Authorizing the Cloudflare Pages deployment.</td></tr><tr><td><code>CLOUDFLARE_ACCOUNT_ID</code></td><td>Selecting the Cloudflare account for the deployment.</td></tr></tbody></table><p>A prerelease published to a public package registry is public forever. Treat that as a publication decision, not as temporary review infrastructure.</p><h2 id="verify-a-subpath-deployment" tabindex="-1">Verify a subpath deployment <a class="header-anchor" href="#verify-a-subpath-deployment" aria-label="Permalink to “Verify a subpath deployment”">​</a></h2><p>A site served beneath a subpath must receive that base path at build time. Otherwise its assets resolve against the domain root and the page loads blank.</p><p>The shipped workflow sets <code>DOCS_BASE</code> to the preview path, and <code>docs/.vitepress/config.ts</code> reads it at build time. Workbench encountered this bug twice: once for assets and once for homepage links.</p><p>Open the deployed preview. Confirm that the page renders and that the homepage links work. A green workflow is not evidence that a subpath deployment is usable.</p><h2 id="remove-it-when-the-work-ends" tabindex="-1">Remove it when the work ends <a class="header-anchor" href="#remove-it-when-the-work-ends" aria-label="Permalink to “Remove it when the work ends”">​</a></h2><p>Teardown belongs to completion. Remove a preview when its pull request closes or the feature is otherwise complete. A preview that outlives its pull request is stale infrastructure nobody owns.</p><h2 id="red-flags" tabindex="-1">Red flags <a class="header-anchor" href="#red-flags" aria-label="Permalink to “Red flags”">​</a></h2><table tabindex="0"><thead><tr><th>Red flag</th><th>Correction</th></tr></thead><tbody><tr><td>“The artifact uploaded successfully.”</td><td>Deploy or install the artifact in the way a reviewer will actually use it.</td></tr><tr><td>“The workflow is green.”</td><td>Open the preview and exercise the changed behavior.</td></tr><tr><td>“We can reuse the production environment.”</td><td>Choose the cheapest isolated review surface instead.</td></tr><tr><td>“Every repository needs every preview.”</td><td>Preview only the surface changed by the proposal.</td></tr><tr><td>“We will leave it up for later.”</td><td>Teardown the preview at completion.</td></tr></tbody></table>',33)])])}const w=t(o,[["render",s]]);export{u as __pageData,w as default};
